import { shadow, surfaceBorder } from "@/jbm/lib/tokens"

// Light surface (use cardDark for dark surfaces)
<div style={{
  boxShadow: shadow.card,
  border: surfaceBorder.card,
}} />

import { useSec, useIn, useFade, useProgress } from "@/jbm/motion/hooks"

const seconds = useSec()
const entrance = useIn(0.2)
const opacity = useFade(0.2)
const progress = useProgress(0.2, 100, 1.5)

<div style={{ opacity, transform: `translateY(${(1 - entrance) * 30}px)` }}>
  {progress.toFixed(0)}% at {seconds.toFixed(2)}s
</div>
// Call inside a Remotion <Composition> or <Player>.

import { RebuildScreens } from "@/jbm/motion/rebuild-screens"

<RebuildScreens w={936} h={1000}
  pieces={[{ kind: "button", at: 1 }, { kind: "input", at: 2.8 }, { kind: "card", at: 5.3 }]}
  again={[12.9, 14.5]} sticker={{ text: "¿otra vez?", at: 13 }} />

import { Propagate } from "@/jbm/motion/propagate"

<Propagate w={936} h={1040} at={0.9} targets={6}
  label={{ text: "una sola fuente de verdad", at: 4 }}
  bug={5.8} fix={6.6} fixed={7.7} recolor={10.5} recolored={11.7} />
// Render inside a Remotion <Composition> or <Player>.

import { TextFill } from "@/jbm/ui/text-fill"

<TextFill text="Una idea toma forma." progress={0.5} style={{ fontSize: 40 }} />
// progress: 0–1, controlled; no internal timer.

import { ScrollTextFill } from "@/jbm/ui/scroll-text-fill"

<ScrollTextFill
  text="Una idea toma forma. Letra por letra."
  height={320}
  distance={640}
  style={{ fontSize: 40 }}
/>
// Self-contained scroll region; respects prefers-reduced-motion.

import { FlipText } from "@/jbm/ui/flip-text"

<FlipText duration={450} style={{ fontSize: 48 }}>Una idea viva.</FlipText>
// Hover individual letters. Click, tap, Enter, or Space flips all.
// A button: do not nest inside another button or link.

import { Folder } from "@/jbm/ui/folder"

<Folder label="Ideas" open={0.6} />
// open: 0 (closed) to 1 (open); no internal timer.

import { ScoreScale } from "@/jbm/ui/score-scale"

<ScoreScale label="Claridad" value={6} min={0} max={10}
  labels={["Por explorar", "Lista para compartir"]}
  formatValue={(v) => `${v} / 10`} />
// Read-only meter; clamps values to the range.

import { Clock } from "@/jbm/ui/clock"

<Clock hours={8} minutes={30} size={64} />
// Explicit time keeps rendering deterministic. No autoplay.

import { pointOn, pathTilt } from "@/jbm/lib/geometry"

const path = [{ x: 40, y: 170 }, { x: 220, y: 50 }, { x: 460, y: 130 }]
const at = pointOn(path, 0.5)
const angle = pathTilt(path, 0.5)
<g transform={`translate(${at.x} ${at.y}) rotate(${angle})`} />

import { Escritorio } from "@/jbm/motion/escritorio"

<svg viewBox="0 0 820 530">
  <Escritorio box={{ x: 30, y: 65, w: 760, h: 420 }}
    cabinet spec={{ finish: "wood", drawerSide: "end" }}
    folders={[{ name: "datos", accent: true }, { name: "notas" }]} open={1} />
</svg>

import { Burbuja } from "@/jbm/motion/burbuja"

<Burbuja words={["Podemos", "reutilizar", "componentes."]}
  highlight={[1]} progress={1} speaker="Tú" />

import { PaperTape, paperAt } from "@/jbm/ui/paper-tape"

<PaperTape length={700} window={320} markers={[{ id: "review", at: 520, label: "revisar" }]} />
// paperAt(700, 520) === 180: marks and attachments share this origin.

import { FolderContents } from "@/jbm/ui/folder-contents"

<FolderContents
  label="proyecto"
  open={1}
  sheet="README.md"
  entries={[
    { id: "scripts", label: "scripts/" },
    { id: "assets", label: "assets/", document: "notas.md", documentReveal: 1 },
  ]}
  width={320}
  style={{ overflow: "visible" }}
/>
